<script setup>
import { reactive, ref, watch } from "vue";
import axios from "axios";
import Swal from "sweetalert2";

const props = defineProps({ data: { type: Object, required: true }, academicYearId: { type: [String, Number], required: true } });
const emit = defineEmits(["updated"]);
const saving = ref(false); const addingCause = ref(false); const addingType = ref(false);
const form = reactive({ risk_thresholds: {}, risk_weights: {}, pattern_settings: {}, alert_settings: {}, recovery_settings: {}, reason: "Ajuste institucional documentado de la configuración preventiva." });
const cause = reactive({ code: "", name: "", category: "", is_sensitive: false, active: true, sort_order: 100, reason: "Incorporación de causa institucional." });
const type = reactive({ code: "", name: "", category: "", family_contact: false, sensitive: false, active: true, sort_order: 100, reason: "Incorporación de tipo de intervención institucional." });
const settingLabels = {
  accumulated_attendance: "Asistencia acumulada", last_30_days: "Últimos 30 días lectivos", last_15_days: "Últimos 15 días lectivos",
  absence_streak: "Racha de ausencias", unjustified_absences: "Ausencias injustificadas", late_arrivals: "Atrasos", previous_case: "Expediente previo",
  minimum_weekday_observations: "Observaciones mínimas por día semanal", weekday_rate_multiplier: "Multiplicador de frecuencia semanal",
  minimum_pattern_occurrences: "Ocurrencias mínimas del patrón", recent_window_school_days: "Ventana lectiva reciente",
  comparison_window_school_days: "Ventana lectiva de comparación", meaningful_change_points: "Cambio significativo en puntos",
  cooldown_days: "Días de espera entre alertas", days_without_intervention: "Días sin intervención", days_without_family_contact: "Días sin contacto familiar",
  auto_open_cases: "Apertura automática de expedientes", minimum_last_30_rate: "Asistencia mínima últimos 30 días",
  minimum_improvement_points: "Mejora mínima en puntos", maximum_absence_streak: "Racha máxima para recuperación",
};
const settingLabel = (key) => settingLabels[key] || String(key || "").replaceAll("_", " ");
const hydrate = () => Object.assign(form, { risk_thresholds: JSON.parse(JSON.stringify(props.data.settings?.risk_thresholds || {})), risk_weights: JSON.parse(JSON.stringify(props.data.settings?.risk_weights || {})), pattern_settings: JSON.parse(JSON.stringify(props.data.settings?.pattern_settings || {})), alert_settings: JSON.parse(JSON.stringify(props.data.settings?.alert_settings || {})), recovery_settings: JSON.parse(JSON.stringify(props.data.settings?.recovery_settings || {})), reason: "Ajuste institucional documentado de la configuración preventiva." });
watch(() => props.data.settings, hydrate, { immediate: true, deep: true });
const save = async () => { saving.value = true; try { await axios.put("/api/attendance-management/configuration/settings", { academic_year_id: Number(props.academicYearId), ...form }); await Swal.fire({ icon: "success", title: "Configuración guardada", text: "Los próximos análisis usarán estos criterios y conservarán trazabilidad.", timer: 1900, showConfirmButton: false }); emit("updated"); } catch (requestError) { await failure(requestError, "No se pudo guardar"); } finally { saving.value = false; } };
const storeCause = async () => { try { await axios.post("/api/attendance-management/configuration/causes", cause); addingCause.value=false; Object.assign(cause,{code:"",name:"",category:"",is_sensitive:false,active:true,sort_order:100}); emit("updated"); } catch (requestError) { await failure(requestError,"No se pudo crear la causa"); } };
const storeType = async () => { try { await axios.post("/api/attendance-management/configuration/intervention-types", type); addingType.value=false; Object.assign(type,{code:"",name:"",category:"",family_contact:false,sensitive:false,active:true,sort_order:100}); emit("updated"); } catch (requestError) { await failure(requestError,"No se pudo crear el tipo"); } };
const failure = (requestError,title) => Swal.fire({ icon:"error",title,text:Object.values(requestError.response?.data?.errors||{})[0]?.[0]||requestError.response?.data?.message||"Revisa los datos." });
</script>

<template>
  <section class="configuration-stack">
    <div class="governance-note"><i class="bx bx-shield-quarter"></i><div><strong>Configuración gobernada y auditable</strong><p>Los umbrales orientan la gestión preventiva, no diagnostican ni sancionan. Cada cambio exige fundamento y queda en la auditoría.</p></div></div>
    <form class="configuration-grid" @submit.prevent="save">
      <article class="config-card"><header><span class="icon green"><i class="bx bx-line-chart"></i></span><div><strong>Umbrales de asistencia</strong><p>Tramos transparentes para la lectura institucional.</p></div></header><div class="fields"><label><span>Adecuada desde</span><div><input v-model.number="form.risk_thresholds.green" type="number" min="0" max="100" step=".1" required><b>%</b></div></label><label><span>Preventiva desde</span><div><input v-model.number="form.risk_thresholds.yellow" type="number" min="0" max="100" step=".1" required><b>%</b></div></label><label><span>En riesgo desde</span><div><input v-model.number="form.risk_thresholds.orange" type="number" min="0" max="100" step=".1" required><b>%</b></div></label></div></article>
      <article class="config-card"><header><span class="icon red"><i class="bx bx-error-circle"></i></span><div><strong>Disparadores críticos</strong><p>Se aplican además del porcentaje acumulado.</p></div></header><div class="fields"><label><span>Racha de ausencias</span><div><input v-model.number="form.risk_thresholds.critical_absence_streak" type="number" min="2" max="30" required><b>días</b></div></label><label><span>Caída reciente</span><div><input v-model.number="form.risk_thresholds.critical_drop_points" type="number" min="1" max="100" step=".1" required><b>pts</b></div></label><label><span>Ausencias recientes</span><div><input v-model.number="form.risk_thresholds.critical_recent_absences" type="number" min="1" max="30" required><b>casos</b></div></label><label><span>Ventana lectiva</span><div><input v-model.number="form.risk_thresholds.critical_recent_school_days" type="number" min="5" max="60" required><b>días</b></div></label></div></article>
      <article class="config-card wide"><header><span class="icon blue"><i class="bx bx-adjust"></i></span><div><strong>Ponderación del riesgo</strong><p>Puntaje explicable: porcentaje, tendencia, rachas, injustificadas y antecedentes.</p></div></header><div class="weight-grid"><label v-for="(value,key) in form.risk_weights" :key="key"><span>{{ settingLabel(key) }}</span><input v-model.number="form.risk_weights[key]" type="range" min="0" max="100"><strong>{{ value }}</strong></label></div></article>
      <article class="config-card wide"><header><span class="icon purple"><i class="bx bx-radar"></i></span><div><strong>Motor de patrones, alertas y recuperación</strong><p>Muestras mínimas, confianza y enfriamiento para evitar falsos positivos repetidos.</p></div></header><div class="json-fields"><label v-for="(value,key) in form.pattern_settings" :key="`pattern-${key}`"><span>{{ settingLabel(key) }}</span><input v-if="typeof value==='number'" v-model.number="form.pattern_settings[key]" type="number" min="0" step=".1"><input v-else-if="typeof value==='boolean'" v-model="form.pattern_settings[key]" type="checkbox"><input v-else v-model="form.pattern_settings[key]"></label><label v-for="(value,key) in form.alert_settings" :key="`alert-${key}`"><span>{{ settingLabel(key) }}</span><input v-if="typeof value==='number'" v-model.number="form.alert_settings[key]" type="number" min="0" step=".1"><input v-else-if="typeof value==='boolean'" v-model="form.alert_settings[key]" type="checkbox"><input v-else v-model="form.alert_settings[key]"></label><label v-for="(value,key) in form.recovery_settings" :key="`recovery-${key}`"><span>{{ settingLabel(key) }}</span><input v-if="typeof value==='number'" v-model.number="form.recovery_settings[key]" type="number" min="0" step=".1"><input v-else-if="typeof value==='boolean'" v-model="form.recovery_settings[key]" type="checkbox"><input v-else v-model="form.recovery_settings[key]"></label></div></article>
      <article class="config-card wide audit-reason"><label><span>Fundamento obligatorio del cambio</span><textarea v-model="form.reason" required rows="2" maxlength="1000"></textarea></label><button type="submit" class="btn btn-primary" :disabled="saving"><span v-if="saving" class="spinner-border spinner-border-sm"></span><i v-else class="bx bx-save"></i>Guardar configuración</button></article>
    </form>

    <div class="catalog-grid"><article class="catalog-card"><header><div><span>CATÁLOGO</span><h2>Causas de ausencia</h2></div><button type="button" @click="addingCause=!addingCause"><i class="bx bx-plus"></i>Nueva causa</button></header><form v-if="addingCause" class="catalog-form" @submit.prevent="storeCause"><input v-model="cause.code" required placeholder="codigo_interno"><input v-model="cause.name" required placeholder="Nombre visible"><input v-model="cause.category" placeholder="Categoría"><label><input v-model="cause.is_sensitive" type="checkbox">Sensible</label><button class="btn btn-primary btn-sm">Guardar</button></form><div class="catalog-list"><div v-for="item in data.absence_reasons || []" :key="item.id"><span><strong>{{ item.name }}</strong><small>{{ item.category || 'Sin categoría' }}</small></span><em v-if="item.is_sensitive"><i class="bx bx-lock-alt"></i>Sensible</em><em v-else>Estándar</em></div></div></article><article class="catalog-card"><header><div><span>CATÁLOGO</span><h2>Tipos de intervención</h2></div><button type="button" @click="addingType=!addingType"><i class="bx bx-plus"></i>Nuevo tipo</button></header><form v-if="addingType" class="catalog-form" @submit.prevent="storeType"><input v-model="type.code" required placeholder="codigo_interno"><input v-model="type.name" required placeholder="Nombre visible"><input v-model="type.category" placeholder="Categoría"><label><input v-model="type.family_contact" type="checkbox">Contacto familiar</label><label><input v-model="type.sensitive" type="checkbox">Sensible</label><button class="btn btn-primary btn-sm">Guardar</button></form><div class="catalog-list"><div v-for="item in data.intervention_types || []" :key="item.id"><span><strong>{{ item.name }}</strong><small>{{ item.category || 'Sin categoría' }}</small></span><em v-if="item.sensitive"><i class="bx bx-lock-alt"></i>Sensible</em><em v-else-if="item.family_contact">Familia</em><em v-else>Gestión</em></div></div></article></div>
  </section>
</template>

<style scoped>
